// @ts-nocheck
// ===== FX3U Computer Link (Dedicated Protocol, Format 1) ผ่าน Waveshare TCP =====
// PLC : FX3U-232-BD · 9600 · 7 bit · Even · 1 Stop · Station 00 · Sum check ON
// แก้รายการที่จะอ่านในตารางนี้ แล้ว Deploy (อ่านทีละบล็อกวนไปเรื่อยๆ)
//  dev: "D" = word (WR) · "M" / "X" / "Y" / "T" / "C" (bit) = อ่านแบบ bit (BR)
//  X / Y ใช้เลขฐาน 8 ตามป้าย PLC (X0–X7, X10–X17 …)
const BLOCKS = [
    { name: "D100-D109", dev: "D", start: 100, count: 10 },
    { name: "M0-M15",    dev: "M", start: 0,   count: 16 },
];
const idx = (context.get("i") || 0) % BLOCKS.length;
context.set("i", idx + 1);
const b = BLOCKS[idx];
const bit = b.dev !== "D";
const addr = (b.dev === "X" || b.dev === "Y") ? b.start.toString(8) : String(b.start);
const head = b.dev + addr.padStart(4, "0");
const cnt = b.count.toString(16).toUpperCase().padStart(2, "0");
const body = "00" + "FF" + (bit ? "BR" : "WR") + "0" + head + cnt;     // สถานี 00 · PC FF · คำสั่ง · wait 0
let sum = 0; for (const ch of body) sum += ch.charCodeAt(0);
const frame = "\x05" + body + (sum & 0xFF).toString(16).toUpperCase().padStart(2, "0");
msg.block = b;
msg.payload = Buffer.from(frame, "ascii");
return msg;

// @ts-nocheck
// ===== ถอดคำตอบจาก FX3U =====
// ปกติ : STX 00 FF <ข้อมูล> ETX <sum>  · ผิดพลาด : NAK 00 FF <รหัส error 2 หลัก>
const b = msg.block || {};
const s = Buffer.isBuffer(msg.payload) ? msg.payload.toString("ascii") : String(msg.payload || "");
const fail = (t) => { const n = (context.get("fail") || 0) + 1; context.set("fail", n);
    node.status({ fill: "red", shape: "ring", text: b.name + " · " + t + " (" + n + ")" }); return null; };
if (!s.length) return fail("ไม่มีคำตอบ (เช็คสาย/ค่า 9600 7E1 / Dedicated Protocol)");
if (s.charCodeAt(0) === 0x15) return fail("NAK error " + s.substr(5, 2));
const st = s.indexOf("\x02"), et = s.indexOf("\x03", st + 1);
if (st < 0 || et < 0) return fail("คำตอบไม่ครบ: " + JSON.stringify(s));
const data = s.substring(st + 5, et);                       // ตัด STX + "00FF"
const out = {};
if (b.dev === "D") {
    for (let k = 0; k < b.count; k++) {
        const hx = data.substr(k * 4, 4); if (hx.length < 4) break;
        let v = parseInt(hx, 16); if (v > 32767) v -= 65536;  // 16-bit มีเครื่องหมาย
        out["D" + (b.start + k)] = v;
    }
} else {
    const oct = b.dev === "X" || b.dev === "Y";
    for (let k = 0; k < b.count && k < data.length; k++)
        out[b.dev + (oct ? (b.start + k).toString(8) : (b.start + k))] = data[k] === "1";
}
context.set("fail", 0);
const all = Object.assign(flow.get("fx3u") || {}, out); flow.set("fx3u", all);
node.status({ fill: "green", shape: "dot", text: b.name + " OK · " + new Date().toLocaleTimeString() });
return { payload: out, block: b.name, all };
